def nom_officiel(ident, langue):
    """Nom de l'objet dans la langue (anglais si le jeu n'a pas cette langue), ou None s'il est inconnu."""
    noms = NOMS.get(ident)
    if not noms:
        return None
    return noms.get(langue) or noms.get("en")
